//! Entire published map inventories and generated bytes retain Native owners.

use serde_json::Value;
use std::fs;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

#[path = "oracle_support/gd2_maps.rs"]
mod maps;
static NEXT: AtomicU64 = AtomicU64::new(0);

#[test]
fn native_javascript_bytes_and_complete_maps_match_native() {
    compare(false, "javascript");
}
#[test]
fn legacy_javascript_bytes_and_complete_maps_match_native() {
    compare(true, "javascript");
}
#[test]
fn native_declaration_bytes_and_complete_maps_match_native() {
    compare(false, "declaration");
}
#[test]
fn legacy_declaration_bytes_and_complete_maps_match_native() {
    compare(true, "declaration");
}

#[test]
fn native_layout_options_preserve_javascript_bytes_and_complete_maps() {
    compare_input(
        false,
        "javascript",
        include_str!("fixtures/program_roots/layout-options-maps.json"),
    );
}
#[test]
fn legacy_layout_options_preserve_javascript_bytes_and_complete_maps() {
    compare_input(
        true,
        "javascript",
        include_str!("fixtures/program_roots/layout-options-maps.json"),
    );
}
#[test]
fn native_layout_options_preserve_declaration_bytes_and_complete_maps() {
    compare_input(
        false,
        "declaration",
        include_str!("fixtures/program_roots/layout-options-maps.json"),
    );
}
#[test]
fn legacy_layout_options_preserve_declaration_bytes_and_complete_maps() {
    compare_input(
        true,
        "declaration",
        include_str!("fixtures/program_roots/layout-options-maps.json"),
    );
}

fn compare(legacy: bool, kind: &str) {
    compare_input(
        legacy,
        kind,
        include_str!("fixtures/program_roots/complete-maps.json"),
    );
}

fn compare_input(legacy: bool, kind: &str, input: &str) {
    let input: Value = serde_json::from_str(input).unwrap();
    let base = std::env::temp_dir().join(format!(
        "bluets-complete-maps-{}-{}",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    fs::create_dir(&base).unwrap();
    for row in input["cases"].as_array().unwrap() {
        if !row["maps"]
            .as_object()
            .unwrap()
            .values()
            .any(|v| v["kind"] == kind)
        {
            continue;
        }
        let root = base.join(row["id"].as_str().unwrap());
        fs::create_dir_all(&root).unwrap();
        for (name, source) in row["files"].as_object().unwrap() {
            let file = root.join(name);
            fs::create_dir_all(file.parent().unwrap()).unwrap();
            fs::write(file, source.as_str().unwrap()).unwrap();
        }
        fs::write(
            root.join("tsconfig.json"),
            serde_json::to_vec_pretty(&row["config"]).unwrap(),
        )
        .unwrap();
        let args = if legacy {
            vec!["build", "--config", "tsconfig.json", "--diagnostics-json"]
        } else {
            vec!["--project", "tsconfig.json", "--diagnostics-json"]
        };
        let output = Command::new(env!("CARGO_BIN_EXE_bluetsc"))
            .args(args)
            .current_dir(&root)
            .output()
            .unwrap();
        fs::write(root.join("stdout.log"), &output.stdout).unwrap();
        fs::write(root.join("stderr.log"), &output.stderr).unwrap();
        assert!(
            output.status.success(),
            "{}; retained {}: {}",
            row["id"],
            root.display(),
            String::from_utf8_lossy(&output.stderr)
        );
        let bytes = if kind == "javascript" {
            &row["javascript"]
        } else {
            &row["declarations"]
        };
        for (name, expected) in bytes.as_object().unwrap() {
            assert_eq!(
                fs::read_to_string(root.join("dist").join(name)).unwrap(),
                expected.as_str().unwrap(),
                "{}: {name}; retained {}",
                row["id"],
                root.display()
            );
        }
        for (name, value) in row["maps"]
            .as_object()
            .unwrap()
            .iter()
            .filter(|(_, v)| v["kind"] == kind)
        {
            let text = fs::read_to_string(root.join("dist").join(name)).unwrap();
            assert_eq!(
                maps::decoded(&text),
                value["expected"],
                "{}: {name}; retained {}",
                row["id"],
                root.display()
            );
        }
    }
    fs::remove_dir_all(base).unwrap();
}
